#!/bin/bash
docker run --rm -v $(pwd):/workspace -w /workspace opensuse/tumbleweed bash -c "zypper --gpg-auto-import-keys rr repo-openh264 || true && zypper --gpg-auto-import-keys refresh || true && zypper --gpg-auto-import-keys -n dup --allow-downgrade --allow-vendor-change && zypper --gpg-auto-import-keys -n install --auto-agree-with-licenses cmake ninja gcc-c++ clang cppcheck kf6-extra-cmake-modules qt6-base-devel qt6-tools-devel qt6-declarative-devel kf6-kcoreaddons-devel kf6-ki18n-devel kf6-kwallet-devel kf6-knotifications-devel kf6-kxmlgui-devel kf6-kconfig-devel kf6-kwidgetsaddons-devel kf6-kauth-devel kf6-karchive-devel kf6-kglobalaccel-devel kf6-kcodecs-devel kf6-kconfigwidgets-devel kf6-kitemviews-devel kf6-kiconthemes-devel kf6-kdbusaddons-devel kf6-kwindowsystem-devel && cmake -B build -S . -G Ninja -DCMAKE_BUILD_TYPE=Release -DQT_MAJOR_VERSION=6 && cmake --build build --parallel"
